import time
from functools import wraps

def chrono(f):
    @wraps(f)
    def enveloppe(*args, **kwargs):
        debut = time.perf_counter()
        resultat = f(*args, **kwargs)
        print(f"{f.__name__} : {time.perf_counter() - debut:.4f} s")
        return resultat
    return enveloppe

class Personne:
    def __init__(self, nom: str, age: int):
        self._nom, self.age = nom, age   # passe par le setter

    @property
    def age(self) -> int:
        return self._age

    @age.setter
    def age(self, valeur: int) -> None:
        if valeur < 0:
            raise ValueError("L'âge doit être positif.")
        self._age = valeur

@chrono
def somme(n: int) -> int:
    """Somme des entiers de 0 à n-1."""
    return sum(range(n))

