class Compte:
    def __init__(self, titulaire: str, solde: float = 0.0):
        self.titulaire = titulaire
        self._solde = solde

    @property
    def solde(self) -> float:
        return self._solde

    def deposer(self, montant: float) -> None:
        if montant <= 0:
            raise ValueError("Montant positif attendu.")
        self._solde += montant

    def retirer(self, montant: float) -> None:
        if montant <= 0 or montant > self._solde:
            raise ValueError("Montant invalide ou solde insuffisant.")
        self._solde -= montant

class CompteEpargne(Compte):
    def appliquer_interets(self, taux: float) -> None:
        self.deposer(self._solde * taux)

c = CompteEpargne("Ana", 100)
c.appliquer_interets(0.03)
print(c.solde)   # 103.0
